                    emailIdx[email] = m
                    emailToAcc[m] = accId
                    m++
                }
            }
        }

        adj = MutableList(m) { mutableListOf() }
        for (account in accounts) {
            for (i in 2 until account.size) {
                val id1 = emailIdx[account[i]]!!
