                adj[id1].add(id2)
                adj[id2].add(id1)
            }
        }

        emailGroup = mutableMapOf()
        visited = BooleanArray(m)

        for (i in 0 until m) {
            if (!visited[i]) {
                emailGroup[emailToAcc[i]!!] = mutableListOf()
                dfs(i, emailToAcc[i]!!)
