        return res
    }

    private fun dfs(node: Int, accId: Int) {
        visited[node] = true
        emailGroup[accId]!!.add(emails[node])
        for (nei in adj[node]) {
            if (!visited[nei]) {
                dfs(nei, accId)
            }
        }
    }
}
