                let email = account[j]
                if let accId = emailToAcc[email] {
                    _ = uf.union(i, accId)
                } else {
                    emailToAcc[email] = i
                }
            }
        }

        var emailGroup = [Int: [String]]()
        for (email, accId) in emailToAcc {
            let leader = uf.find(accId)
            if emailGroup[leader] == nil {
                emailGroup[leader] = []
            }
            emailGroup[leader]!.append(email)
        }

        var res = [[String]]()
        for (accId, emails) in emailGroup {
            let sortedEmails = emails.sorted()
            var merged = [accounts[accId][0]]
            merged.append(contentsOf: sortedEmails)
            res.append(merged)
        }

        return res
    }
}

